import{I as i,o as c,c as p,j as e,a as o,J as n,w as s,b6 as m,bz as h,bA as b}from"./chunks/framework.BUXTSoD9.js";const f={style:{margin:"50px 0"}},P=JSON.parse('{"title":"Pensamiento de producto y diseno de soluciones","description":"Como pasar de \\"construir una herramienta\\" a \\"disenar un producto valioso\\": fuentes de ideas, descomposicion en MVP, mejora de UX y uso razonable de IA.","frontmatter":{"title":"Pensamiento de producto y diseno de soluciones","description":"Como pasar de \\"construir una herramienta\\" a \\"disenar un producto valioso\\": fuentes de ideas, descomposicion en MVP, mejora de UX y uso razonable de IA."},"headers":[],"relativePath":"es-es/stage-1/appendix-a-product-thinking/index.md","filePath":"es-es/stage-1/appendix-a-product-thinking/index.md"}'),_={name:"es-es/stage-1/appendix-a-product-thinking/index.md"},x=Object.assign(_,{setup(g){const r="Aprox. <strong>6 horas</strong>";return(v,a)=>{const l=i("ChapterIntroduction"),t=i("StepBar"),d=i("ClientOnly"),u=i("RelatedArticlesSection");return c(),p("div",null,[a[1]||(a[1]=e("h1",{id:"pensamiento-de-producto-y-diseno-de-soluciones",tabindex:"-1"},[o("Pensamiento de producto y diseno de soluciones "),e("a",{class:"header-anchor",href:"#pensamiento-de-producto-y-diseno-de-soluciones","aria-label":"Permalink to “Pensamiento de producto y diseno de soluciones”"},"​")],-1)),a[2]||(a[2]=e("h2",{id:"introduccion-del-capitulo",tabindex:"-1"},[o("Introduccion del capitulo "),e("a",{class:"header-anchor",href:"#introduccion-del-capitulo","aria-label":"Permalink to “Introduccion del capitulo”"},"​")],-1)),n(l,{duration:r,tags:["Producto","Necesidades","Diseno de soluciones","Insights de usuario"],coreOutput:"1 esquema completo de producto",expectedOutput:"Ideas de producto ejecutables"},{default:s(()=>[...a[0]||(a[0]=[e("p",null,[o("En capitulos anteriores ya aprendiste a construir prototipos con AI IDEs. Aqui cambiamos el foco de "),e("strong",null,'"puedo construirlo?"'),o(" a "),e("strong",null,'"que vale la pena construir?"'),o(".")],-1),e("p",null,"Vamos a trabajar un metodo repetible para:",-1),e("ol",null,[e("li",null,"Encontrar ideas mas confiables (no solo inspiracion)."),e("li",null,"Convertir una idea en un flujo de producto construible."),e("li",null,'Pasar de "funciona" a "se usa de verdad".'),e("li",null,'Usar IA donde aumenta el valor y no solo "se ve cool".')],-1)])]),_:1}),e("div",f,[n(d,null,{default:s(()=>[n(t,{active:0,items:[{title:"Fuentes de ideas",description:"Encontrar ideas confiables"},{title:"Descomposicion",description:"Convertir idea en app construible"},{title:"Mejora",description:"De usable a buena"},{title:"IA como amplificador",description:"Aplicar IA donde aporta valor"}]})]),_:1})]),a[3]||(a[3]=m('<h2 id="lo-que-aprenderas" tabindex="-1">Lo que aprenderas <a class="header-anchor" href="#lo-que-aprenderas" aria-label="Permalink to “Lo que aprenderas”">​</a></h2><p>Al final deberias poder responder:</p><ol><li>De donde salen ideas confiables?</li><li>Como descomponer una idea en un MVP construible?</li><li>Como evaluar y mejorar una app para que la gente la use?</li><li>Donde usar IA para amplificar valor?</li><li>Como conseguir los primeros usuarios reales?</li></ol><hr><h1 id="_1-fuentes-de-ideas-confiables" tabindex="-1">1. Fuentes de ideas confiables <a class="header-anchor" href="#_1-fuentes-de-ideas-confiables" aria-label="Permalink to “1. Fuentes de ideas confiables”">​</a></h1><p>No necesitas una &quot;idea genial&quot;. Necesitas un problema real en un escenario real.</p><h2 id="_1-1-que-es-una-idea-en-sentido-de-producto" tabindex="-1">1.1 Que es una idea (en sentido de producto)? <a class="header-anchor" href="#_1-1-que-es-una-idea-en-sentido-de-producto" aria-label="Permalink to “1.1 Que es una idea (en sentido de producto)?”">​</a></h2><p>Una idea construible tiene al menos:</p><ol><li>Un usuario objetivo claro (quien exactamente?).</li><li>Un escenario concreto (cuando/donde ocurre).</li><li>Una tarea concreta (que quiere lograr).</li><li>Una mejora plausible frente a como se hace hoy.</li></ol><h2 id="_1-2-idea-vs-necesidad-real" tabindex="-1">1.2 Idea vs necesidad real <a class="header-anchor" href="#_1-2-idea-vs-necesidad-real" aria-label="Permalink to “1.2 Idea vs necesidad real”">​</a></h2><p>Una idea es una hipotesis. Una necesidad real es algo que el usuario ya intenta resolver (aunque sea con workarounds).</p><p>Regla rapida:</p><ul><li>Necesidad real: el usuario ya paga con tiempo/dinero/estres.</li><li>Necesidad falsa: el usuario dice &quot;interesante&quot;, pero no cambia conducta ni paga.</li></ul><p><img src="'+h+'" alt=""></p><h2 id="_1-3-por-que-algunas-ideas-crecen-solas" tabindex="-1">1.3 Por que algunas ideas crecen solas <a class="header-anchor" href="#_1-3-por-que-algunas-ideas-crecen-solas" aria-label="Permalink to “1.3 Por que algunas ideas crecen solas”">​</a></h2><p>Cuando el valor es inmediato y el flujo es corto, la recomendacion aparece de forma natural:</p><p>Problema -&gt; valor pequeno inmediato -&gt; repeticion -&gt; recomendacion.</p><p>Si el producto necesita mucha explicacion o empuje externo, suele ser senal de que el dolor no es fuerte.</p><h2 id="_1-4-cuatro-fuentes-estables" tabindex="-1">1.4 Cuatro fuentes estables <a class="header-anchor" href="#_1-4-cuatro-fuentes-estables" aria-label="Permalink to “1.4 Cuatro fuentes estables”">​</a></h2><ol><li>Tu trabajo: procesos repetitivos, coordinacion, reportes, QA.</li><li>Comunidades: preguntas repetidas y quejas recurrentes.</li><li>Reviews/comentarios: fricciones y &quot;por que esto es tan dificil?&quot;.</li><li>Productos existentes: encontrar huecos (caro, complejo, poco especializado).</li></ol><p><img src="'+b+'" alt=""></p><hr><h1 id="_2-descomposicion-de-idea-a-app" tabindex="-1">2. Descomposicion: de idea a app <a class="header-anchor" href="#_2-descomposicion-de-idea-a-app" aria-label="Permalink to “2. Descomposicion: de idea a app”">​</a></h1><p>Una idea se vuelve construible cuando se convierte en decisiones.</p><h2 id="_2-1-minimo-usuario-escenario-flujo" tabindex="-1">2.1 Minimo: usuario, escenario, flujo <a class="header-anchor" href="#_2-1-minimo-usuario-escenario-flujo" aria-label="Permalink to “2.1 Minimo: usuario, escenario, flujo”">​</a></h2><p>Define:</p><ol><li>Usuario: rol, objetivo, restricciones, presupuesto.</li><li>Escenario: disparador -&gt; pasos -&gt; resultado.</li><li>Flujo principal: 3-7 pasos que entregan valor.</li></ol><h2 id="_2-2-cortar-alcance-mvp" tabindex="-1">2.2 Cortar alcance (MVP) <a class="header-anchor" href="#_2-2-cortar-alcance-mvp" aria-label="Permalink to “2.2 Cortar alcance (MVP)”">​</a></h2><p>Un MVP no es &quot;menos features&quot;, es &quot;una promesa clara que se cumple&quot;.</p><p>Preguntas utiles:</p><ul><li>Cual es el primer minuto donde el usuario dice &quot;esto me ahorro tiempo&quot;?</li><li>Que se puede quitar sin romper el valor central?</li><li>Cual es la suposicion mas riesgosa? (validala primero)</li></ul><hr><h1 id="_3-mejora-de-usable-a-buena" tabindex="-1">3. Mejora: de usable a buena <a class="header-anchor" href="#_3-mejora-de-usable-a-buena" aria-label="Permalink to “3. Mejora: de usable a buena”">​</a></h1><p>Despues del MVP, el trabajo es:</p><ol><li>Claridad: el usuario entiende el siguiente paso sin leer manual.</li><li>Friccion baja: menos clicks, menos formularios, menos contexto.</li><li>Confianza: datos claros, resultados explicables, defaults seguros.</li></ol><p>Test simple: un usuario nuevo obtiene valor en 60 segundos?</p><hr><h1 id="_4-ia-como-amplificador-de-valor" tabindex="-1">4. IA como amplificador de valor <a class="header-anchor" href="#_4-ia-como-amplificador-de-valor" aria-label="Permalink to “4. IA como amplificador de valor”">​</a></h1><p>La IA aporta mas cuando:</p><ol><li>Convierte lenguaje en estructura (texto -&gt; tareas, notas -&gt; plan).</li><li>Resume y prioriza (mucho contenido -&gt; accion).</li><li>Personaliza (recomendaciones segun contexto).</li></ol><p>Suele aportar poco cuando solo se pega un chat sin mejorar el flujo central.</p><hr><h2 id="output-esperado" tabindex="-1">Output esperado <a class="header-anchor" href="#output-esperado" aria-label="Permalink to “Output esperado”">​</a></h2><p>Un esquema de producto que incluya:</p><ol><li>Usuario y caso de uso</li><li>Problema central y coste actual</li><li>Flujo principal (3-7 pasos)</li><li>Alcance del MVP</li><li>Plan de validacion (7 dias) y metricas</li></ol>',45)),n(u)])}}});export{P as __pageData,x as default};
